custom_css:
/*【星月法师】宁宁 × Claude 自制
  素材：Ttsningning/orange-shop-assets1 仓库 starmage 文件夹
  结构参考了易碎蝶老师的拼接气泡思路，代码为重新编写
  ⭕ 想调位置、颜色、文字，只改下面 :root 里的变量就行 */

@import url("https://cdn.jsdelivr.net/npm/lxgw-wenkai-screen-webfont/style.css");

/* ================= 变量调试处 ================= */
:root {
    --输入框文字: "把咒语写在星光里……";
    --加载更多文字: "";
    --气泡宽: min(96vw, 600px);     /* 气泡宽度，手机端约等于全屏 */
    --楼层间距: 26px;               /* 两条消息之间的空隙 */
    --拼接缝: 3px;                   /* 头部/正文/尾部三张卡片之间的缝 */
    --正文字色: #262d57;
    --名字颜色: #f1f3fe;
    --信息颜色: #e6e9fd;             /* 楼层号、计时、字数 */
    --强调蓝: #3a48a6;               /* 强调色（酒红） */
    --浅线: #b8bee0;
    --面板底色: rgba(242, 243, 252, .97);
    --字体: "LXGW WenKai Screen", "LXGW WenKai", "PingFang SC", "Microsoft YaHei", sans-serif;

    /* 以下由宽度自动换算，一般不用动 */
    --比例: calc(var(--气泡宽) / 660);   /* 素材 1 像素换算成屏幕多少 */
    --头高: calc(var(--气泡宽) * 0.30455);
    --头上移: calc(var(--气泡宽) * 0.24091); /* 头部卡片高出正文顶的距离 */
    --尾高: calc(var(--气泡宽) * 0.16667);
}

/* 支持容器单位的浏览器按聊天区宽度算，电脑端宽屏也不会撑爆 */
@supports (width: 1cqw) {
    :root { --气泡宽: min(96cqw, 600px); }
}

body {
    font-family: var(--字体);
}

/* ================= 聊天区 ================= */
#chat {
    container-type: inline-size;
    padding-left: 0 !important;
    padding-right: 0 !important;
    scrollbar-width: none;
}
#chat::-webkit-scrollbar { display: none; }

/* ---------- 气泡正文：九宫格拉伸，多长都不会断 ---------- */
#chat .mes {
    display: block !important;
    box-sizing: border-box;
    width: var(--气泡宽) !important;
    max-width: none !important;
    margin: calc(var(--头上移) + var(--楼层间距)) auto var(--尾高) !important;
    padding: calc(var(--气泡宽) * 0.105) calc(var(--气泡宽) * 0.08) calc(var(--气泡宽) * 0.055) !important;
    min-height: calc(var(--气泡宽) * 0.2);
    flex: 0 0 auto !important;      /* 聊天区是竖向 flex，消息多时不许被压扁 */
    position: relative;
    overflow: visible !important;
    background: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    border: 0 solid transparent !important;
    border-image-source: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/bubble_mid.png") !important;
    border-image-slice: 40 52 40 52 fill !important;
    border-image-width: calc(var(--比例) * 40) calc(var(--比例) * 52) calc(var(--比例) * 40) calc(var(--比例) * 52) !important;
    border-image-repeat: stretch !important;
    color: var(--正文字色);
}
#chat .mes:first-of-type { margin-top: calc(var(--头上移) + 12px) !important; }

/* 兼容修正：TauriTavern / 部分 iOS 客户端会给每条消息加尺寸约束（contain），
   消息高度就不再跟着文字长，正文会溢出、几层叠在一起。这里统一解除 */
#chat > .mes,
#chat > .mes:not(.last_mes),
#chat > .mes.last_mes {
    content-visibility: visible !important;
    contain-intrinsic-block-size: none !important;
    contain-intrinsic-size: none !important;
    contain: none !important;
    height: auto !important;
    max-height: none !important;
}
#chat .mes .mes_block,
#chat .mes .mes_text {
    height: auto !important;
    max-height: none !important;
    contain: none !important;
}
#chat .last_mes .mesAvatarWrapper { padding-bottom: 0 !important; }

/* 头部卡片（头像圈 + 名字牌 + 夜海） */
#chat .mes::before,
#chat .mes::after {
    content: "";
    position: absolute;
    background-repeat: no-repeat;
    background-size: 100% 100%;
    pointer-events: none;
}
#chat .mes::before {
    top: calc(var(--头上移) * -1);
    left: calc(var(--比例) * -25);
    width: calc(var(--比例) * 692);
    height: var(--头高);
    z-index: 1;
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/bubble_top.png");
}
/* 尾部卡片（星星挂饰的海面） */
#chat .mes::after {
    top: calc(100% + var(--比例) * 12);
    left: calc(var(--比例) * -11);
    width: calc(var(--比例) * 667);
    height: var(--尾高);
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/bubble_bot.png");
}

/* ---------- 头像：放进头部卡片的圆框里 ---------- */
#chat .mes .mesAvatarWrapper {
    position: absolute !important;
    left: calc(var(--比例) * -25);
    top: calc(var(--头上移) * -1) !important;
    bottom: auto !important;
    width: calc(var(--比例) * 692);
    height: var(--头高);
    margin: 0 !important;
    /* 楼层号/计时/字数排成一行，数字再长也不会叠在一起 */
    padding: calc(var(--头高) * 0.61692) 0 0 33.82% !important;
    box-sizing: border-box;
    display: flex !important;
    flex-direction: row !important;
    align-items: flex-start !important;
    justify-content: flex-start !important;
    gap: calc(var(--气泡宽) * 0.022);
    pointer-events: none;
    z-index: 2;
}
#chat .mes .mesAvatarWrapper .avatar {
    position: absolute !important;
    left: 6.72%;
    top: 11.94%;     /* 头像上下：数字越小越往上 */
    width: 21.10% !important;
    height: auto !important;
    aspect-ratio: 1;
    margin: 0 !important;
    border-radius: 50% !important;
    overflow: hidden;
    pointer-events: auto;
    box-shadow: none;
}
/* 珍珠圈单独一层盖在头像上面：头像只从圈中间露出来，不会压住珍珠和蝴蝶结 */
#chat .mes .mesAvatarWrapper::after {
    content: "";
    position: absolute;
    inset: 0;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ring_overlay.png") 0 0 / 100% 100% no-repeat;
    pointer-events: none;
    z-index: 2;
}
#chat .mes .mesAvatarWrapper .avatar { z-index: 1; }
#chat .mes .mesAvatarWrapper .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
    border-radius: 50% !important;
    border: 0 !important;
    box-shadow: none !important;
}

/* ---------- 楼层号 / 计时 / 字数：写在头部的夜空上 ---------- */
#chat .mes .mesIDDisplay,
#chat .mes .mes_timer,
#chat .mes .tokenCounterDisplay {
    position: relative !important;
    z-index: 3;
    flex: none;
    width: auto !important;
    margin: 0 !important;
    padding: 0 !important;
    font-size: calc(var(--气泡宽) * 0.027) !important;
    line-height: 1;
    color: var(--信息颜色) !important;
    opacity: .95 !important;
    white-space: nowrap;
    text-shadow: 0 0 4px rgba(16, 25, 84, .95);
}

/* ---------- 名字：放进名字牌 ---------- */
#chat .mes .mes_block {
    position: static !important;
    margin: 0 !important;
    padding: 0 !important;
    width: 100%;
}
#chat .mes .ch_name {
    position: absolute !important;
    left: calc(var(--比例) * -25);
    top: calc(var(--头上移) * -1);
    bottom: auto;
    width: calc(var(--比例) * 692);
    height: var(--头高);
    display: block !important;
    z-index: 3;
    pointer-events: none;
}
#chat .mes .ch_name .name_text {
    position: absolute;
    left: 28.90%;
    top: 17.41%;
    width: 21.39%;
    height: 19.40%;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    white-space: nowrap;
    font-size: calc(var(--气泡宽) * 0.034);
    font-weight: 600;
    letter-spacing: 1px;
    color: var(--名字颜色);
    text-shadow: 0 0 6px rgba(23, 35, 112, 1), 0 1px 2px rgba(9, 15, 56, .7);
    pointer-events: auto;
}
#chat .mes .timestamp {
    position: absolute;
    left: 30%;
    top: 80%;
    font-size: calc(var(--气泡宽) * 0.024);
    color: var(--信息颜色) !important;
    text-shadow: 0 0 4px rgba(16, 25, 84, .95);
    white-space: nowrap;
}
#chat .mes .mes_ghost {
    position: absolute;
    left: 50%;
    top: 26%;
    color: #fff;
}

/* ---------- 编辑按钮：头部右上 ---------- */
#chat .mes .mes_buttons,
#chat .mes .mes_edit_buttons {
    position: absolute !important;
    right: 3.5%;
    top: 59.70%;
    margin: 0 !important;
    padding: 0 !important;
    align-items: center;
    gap: 4px;
    pointer-events: auto;
    filter: none !important;
}
#chat .mes .mes_buttons { display: flex; }
#chat .mes .mes_buttons .mes_button,
#chat .mes .mes_buttons .extraMesButtons > div {
    opacity: 1 !important;
    filter: none !important;
    color: #fff !important;
    text-shadow: 0 0 4px rgba(16, 25, 84, .95);
}
#chat .mes .extraMesButtons {
    background: rgba(33, 45, 122, .6);
    border-radius: 999px;
    padding: 2px 6px;
}
#chat .mes .mes_edit_buttons .menu_button {
    width: 26px;
    height: 26px;
    padding: 0 !important;
    margin: 0 !important;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
}

/* ---------- 翻页箭头 + 计数：尾部卡片上 ---------- */
#chat .mes .swipe_left,
#chat .mes .swipeRightBlock {
    position: absolute !important;
    top: calc(100% + var(--尾高) * 0.1) !important;
    bottom: auto !important;
    z-index: 5;
    margin: 0 !important;
}
#chat .mes .swipe_left { left: 3.5% !important; right: auto !important; }
#chat .mes .swipeRightBlock {
    right: 3.5% !important;
    left: auto !important;
    display: flex;
    flex-direction: row-reverse !important;
    align-items: center;
    gap: 6px;
}
#chat .mes .swipes-counter {
    position: static !important;
    margin: 0 !important;
    font-size: 11px;
    color: #fff !important;
    opacity: 1 !important;
    text-shadow: 0 0 4px rgba(16, 25, 84, 1);
}

/* ---------- 正文排版 ---------- */
#chat .mes .mes_text {
    padding: 0 !important;
    color: var(--正文字色);
    line-height: 1.85;
    letter-spacing: .02em;
    text-align: justify;
    overflow-wrap: anywhere;
}
#chat .mes .mes_text em,
#chat .mes .mes_text i { color: var(--SmartThemeEmColor); }
#chat .mes .mes_text q {
    color: var(--SmartThemeQuoteColor);
    background: linear-gradient(transparent 62%, rgba(157, 167, 233, .35) 62%);
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
}
#chat .mes .mes_text strong { color: #273486; }
.mes_text blockquote,
.mes_reasoning blockquote {
    border-left: 3px solid #919ad3 !important;
    background: rgba(255, 255, 255, .45) !important;
    border-radius: 0 10px 10px 0;
    padding: 4px 10px !important;
    margin: 6px 0;
}
.mes_text code,
.mes_text pre {
    background: rgba(255, 255, 255, .6) !important;
    border: 1px solid var(--浅线) !important;
    border-radius: 8px;
    color: var(--正文字色) !important;
}
::selection { background: rgba(58, 72, 166, .85); color: #fff; }

/* 分割线 --- ：两道细线夹一颗星 */
.mes_text hr {
    all: unset;
    display: block;
    height: 22px;
    margin: 10px 0;
    background:
        url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/deco_small.png") center / auto 100% no-repeat,
        linear-gradient(90deg, transparent, #c99a7c 15%, #c99a7c 44%, transparent 46%, transparent 54%, #c99a7c 56%, #c99a7c 85%, transparent) center / 100% 1.5px no-repeat;
}

/* ---------- 思维链 ---------- */
#chat .mes .mes_reasoning_details {
    margin: 0 0 12px !important;
    padding: 6px 10px !important;
    background: rgba(255, 255, 255, .42);
    border: 1px solid rgba(145, 154, 211, .5);
    border-radius: 14px;
}
#chat .mes .mes_reasoning_header {
    background: none !important;
    color: var(--强调蓝) !important;
    padding-left: 26px !important;
    position: relative;
}
#chat .mes .mes_reasoning_header::before {
    content: "";
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
    width: 20px;
    height: 18px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/deco_small.png") center / contain no-repeat;
}
#chat .mes .mes_reasoning {
    color: #4f5685 !important;
    border-left: 2px solid var(--浅线) !important;
    padding-left: 8px !important;
}

/* ---------- 编辑框 ---------- */
#chat .mes .edit_textarea {
    background: rgba(255, 255, 255, .8) !important;
    border: 1px solid var(--浅线) !important;
    border-radius: 12px !important;
    color: var(--正文字色) !important;
}

/* 加载更多消息 */
#show_more_messages {
    width: 168px;
    height: 42px;
    margin: 24px auto 0 !important;
    padding: 0 !important;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/btn_loadmore.png") center / contain no-repeat !important;
    border: 0 !important;
    box-shadow: none !important;
    color: transparent !important;
    font-size: 0 !important;
}

/* ================= 顶栏 ================= */
#top-bar {
    background: none !important;
    box-shadow: none !important;
    border: 0 solid transparent !important;
    border-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/topbar.png") 48 70 48 70 fill / 19px 26px !important;
    backdrop-filter: none !important;
}
.drawer-icon.fa-fw::before,
.drawer-icon.fa-fw::after { content: "" !important; }
.drawer-icon.fa-fw {
    width: 30px !important;
    height: 30px !important;
    font-size: 0 !important;
    background: center / contain no-repeat;
    opacity: 1 !important;
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/deco_small.png");   /* 插件加的图标没有专属图时，默认用小爱心，不会空白 */
    filter: drop-shadow(0 0 3px rgba(218, 223, 252, .7));
    transition: transform .25s ease;
}
.drawer-icon.fa-fw.openIcon { transform: translateY(2px) scale(1.08); }
#ai-config-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_brain.png"); }
#sys-settings-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_chat.png"); }
#advanced-formatting-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_pencil.png"); }
#WI-SP-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_book.png"); }
#user-settings-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_gear.png"); }
#backgrounds-drawer-toggle .drawer-icon,
#logo_block .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/tile_a.png"); }
#extensions-settings-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/btn_plus.png"); }
#persona-management-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_star_on.png"); }
#rightNavHolder .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/tile_b.png"); }

/* ================= 图标替换 ================= */
.mes .swipe_left::before,
.mes .swipe_right::before,
.mes_button.extraMesButtonsHint::before,
.mes_button.mes_edit::before,
.mes_edit_done::before,
.mes_edit_cancel::before,
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#mes_stop .fa-circle-stop::before,
.inline-drawer-icon::before,
#favorite_button::before,
#load-spinner::before,
#load-spinner::after {
    content: none !important;
    display: none !important;
}

.mes .swipe_left,
.mes .swipe_right {
    width: 26px !important;
    height: 26px !important;
    font-size: 0 !important;
    background: center / contain no-repeat !important;
    opacity: 1 !important;
    filter: drop-shadow(0 0 3px rgba(16, 25, 84, .5));
}
.mes .swipe_left { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_left.png") !important; }
.mes .swipe_right { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_right.png") !important; }

.mes_button.extraMesButtonsHint,
.mes_button.mes_edit {
    width: 26px !important;
    height: 22px !important;
    font-size: 0 !important;
    padding: 0 !important;
    background: center / contain no-repeat !important;
}
.mes_button.extraMesButtonsHint { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_more.png") !important; }
.mes_button.mes_edit { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_pencil.png") !important; }

.mes_edit_done.menu_button,
.mes_edit_cancel.menu_button {
    font-size: 0 !important;
    background: center / contain no-repeat !important;
    border: 0 !important;
    box-shadow: none !important;
}
.mes_edit_done.menu_button { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_check.png") !important; }
.mes_edit_cancel.menu_button { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_close.png") !important; }

#options_button,
#extensionsMenuButton,
#send_but,
#mes_stop .fa-circle-stop {
    width: 36px !important;
    height: 36px !important;
    font-size: 0 !important;
    background: center / 32px auto no-repeat !important;
    opacity: 1 !important;
}
/* 输入框按钮上下位置：数字越大越往下 */
#options_button,
#extensionsMenuButton,
#send_but,
#mes_stop .fa-circle-stop { transform: translateY(3px); }
#options_button { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/btn_menu.png") !important; }
#extensionsMenuButton { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/btn_plus.png") !important; }
#send_but { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/btn_send.png") !important; }
#mes_stop .fa-circle-stop { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/btn_stop.png") !important; }

.inline-drawer-icon {
    width: 22px !important;
    height: 18px !important;
    font-size: 0 !important;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_down.png") center / contain no-repeat !important;
    transition: transform .25s ease;
}
.inline-drawer-icon.up { transform: rotate(180deg); }

#favorite_button {
    width: 26px;
    height: 24px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_star.png") center / contain no-repeat !important;
}
#favorite_button.fav_on { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_star_on.png") !important; }

#load-spinner {
    width: 64px;
    height: 64px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/spinner.png") center / contain no-repeat;
    animation: ms-spin 1.4s linear infinite;
}
@keyframes ms-spin { to { transform: rotate(360deg); } }

/* ================= 输入框 ================= */
#form_sheld { background: transparent !important; }
#send_form {
    position: relative;
    min-height: 54px;
    padding: 4px 14px !important;
    background: none !important;
    box-shadow: none !important;
    border: 0 solid transparent !important;
    border-radius: 0 !important;
    border-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/input_bar.png") 48 120 30 60 fill / 24px 60px 15px 30px !important;
    backdrop-filter: none !important;
    overflow: visible !important;
}
#send_form::before {
    content: "";
    position: absolute;
    right: 92px;
    top: -26px;
    width: 26px;
    height: 36px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/deco_bottle.png") center / contain no-repeat;
    pointer-events: none;
    animation: ms-bob 3.6s ease-in-out infinite;
    z-index: 2;
}
@keyframes ms-bob {
    0%, 100% { transform: translateY(0) rotate(-2deg); }
    50% { transform: translateY(-3px) rotate(2deg); }
}
#send_form:has(#send_textarea:focus-visible) { outline: none; }
#send_textarea {
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
    color: var(--正文字色) !important;
    resize: none;
}
#send_textarea::placeholder { color: transparent !important; }
#nonQRFormItems { position: relative; }
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--输入框文字);
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    font-size: 14px;
    color: #6f77ab;
    white-space: nowrap;
    pointer-events: none;
    letter-spacing: 2px;
    z-index: 1;
}

/* ================= 面板 & 设置页 ================= */
.drawer-content,
#right-nav-panel,
#left-nav-panel,
#floatingPrompt,
#cfgConfig {
