}
.standoutHeader > *,
#user-settings-block h4 > *,
#extensions_settings .inline-drawer-header > *,
#extensions_settings2 .inline-drawer-header > * { color: #fff !important; }
.standoutHeader::before,
#user-settings-block h4::before,
#extensions_settings .inline-drawer-toggle.inline-drawer-header::before,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header::before {
    content: "";
    position: absolute;
    left: 9px;
    top: 50%;
    transform: translateY(-50%);
    width: 18px;
    height: 18px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/deco_small.png") center / contain no-repeat;
}

.menu_button {
    background: linear-gradient(180deg, #f9f9fe, #d8dcf4) !important;
    color: var(--正文字色) !important;
    border: 1px solid #aeb4d9 !important;
    border-radius: 999px !important;
    box-shadow: inset 0 1px 0 #fff, 0 2px 4px rgba(27, 37, 103, .15) !important;
    filter: none !important;
}
.menu_button:hover { background: linear-gradient(180deg, #ffffff, #c4c9ec) !important; }

.text_pole,
textarea:not(#send_textarea),
select,
input:not([type="checkbox"], [type="radio"], [type="range"], [type="file"], [type="image"], [type="color"]) {
    background: rgba(255, 255, 255, .85) !important;
    border: 1px solid #bbc0e0 !important;
    border-radius: 10px !important;
    color: var(--正文字色) !important;
    box-shadow: inset 0 1px 3px rgba(27, 37, 103, .1) !important;
}

input[type="checkbox"] {
    background-color: #fff !important;
    border: 1.5px solid #9ea5cf !important;
    border-radius: 5px !important;
    box-shadow: none !important;
}
input[type="checkbox"]:checked { background-color: #3a48a6 !important; }

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 18px;
    height: 28px;
    border: 0;
    border-radius: 0;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/deco_lantern.png") center / contain no-repeat;
    box-shadow: none;
}
.neo-range-slider {
    height: 4px !important;
    background: #c2c7e9 !important;
    border-radius: 999px !important;
    box-shadow: none !important;
}

/* 预设列表 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    background: rgba(255, 255, 255, .75) !important;
    border: 1px solid #babfe2 !important;
    border-radius: 12px !important;
    margin-bottom: 6px;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled {
    background: rgba(224, 226, 243, .6) !important;
    opacity: .75;
}

/* 角色列表 & 头像 */
.character_select,
.bogus_folder_select,
.avatar-container {
    border-radius: 14px !important;
    background: rgba(255, 255, 255, .55) !important;
    border: 1px solid #cbcfe9 !important;
    margin-top: 6px;
}
.character_select.is_fav .avatar { outline: none !important; }
.character_select .avatar img,
.avatar-container .avatar img,
#quickPersonaImg {
    border-radius: 50% !important;
    border: 2px solid #fff !important;
    box-shadow: 0 0 0 1.5px #e9c9a8, 0 0 8px rgba(58, 72, 166, .35) !important;
}
.world_set,
.toggleEnabled,
.fav_on { color: var(--强调蓝) !important; }
.tag {
    background: #e2e5f6 !important;
    color: var(--强调蓝) !important;
    border: 1px solid #bbc0e0 !important;
    border-radius: 999px !important;
}

/* 弹窗、菜单 */
#options,
#extensionsMenu,
.popup,
.list-group,
#select_chat_popup {
    background: var(--面板底色) !important;
    border: 1.5px solid #babfe2 !important;
    border-radius: 16px !important;
    box-shadow: 0 10px 28px rgba(27, 37, 103, .28) !important;
    color: var(--正文字色) !important;
}

/* 通知 */
#toast-container > .toast {
    background: var(--面板底色) !important;
    border: 1.5px solid #babfe2 !important;
    border-radius: 16px !important;
    box-shadow: 0 6px 20px rgba(27, 37, 103, .3) !important;
    padding: 10px 14px 10px 48px !important;
    opacity: 1 !important;
    position: relative;
}
#toast-container > .toast::before {
    content: "";
    position: absolute;
    left: 10px;
    top: 50%;
    transform: translateY(-50%);
    width: 30px;
    height: 30px;
    background: center / contain no-repeat;
}
#toast-container > .toast-success::before,
#toast-container > .toast-info::before { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_check.png"); }
#toast-container > .toast-error::before,
#toast-container > .toast-warning::before { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets1@8a19c730f87c/starmage/ico_close.png"); }
.toast-title,
.toast-message { color: var(--正文字色) !important; }

/* 隐藏快捷回复，点输入框时再出现 */
.qr--buttons {
    max-height: 0;
    opacity: 0;
    overflow: hidden;
    transition: max-height .4s ease, opacity .3s ease;
}
#send_form:focus-within .qr--buttons {
    max-height: 120px;
    opacity: 1;
}

::-webkit-scrollbar { width: 4px; height: 4px; }
::-webkit-scrollbar-thumb { background: #a7add5; border-radius: 4px; }
